  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { LanguageProvider } from './contexts/LanguageContext';
  5→import { useTranslation } from './hooks/useTranslation';
  6→import { AgentProvider } from './contexts/AgentContext';
  7→import { ConfigProvider } from './contexts/ConfigContext';
  8→import { FileUpload } from './components/FileUpload';
  9→import { QueryEditor } from './components/QueryEditor';
 10→import { ResultsTable } from './components/ResultsTable';
 11→import { ResultMarkdown } from './components/ResultMarkdown';
 12→import { Sidebar } from './components/Sidebar';
 13→import { ErrorMessage } from './components/ErrorMessage';
 14→import { AgentPanel } from './components/AgentPanel';
 15→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 16→import './App.css';
 17→
 18→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 19→  const { theme, toggleTheme } = useTheme();
 20→  const { language, setLanguage, t } = useTranslation();
 21→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 22→  const [error, setError] = useState<string | null>(null);
 23→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 24→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 25→  );
 26→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 27→  const [agentOpen, setAgentOpen] = useState(true);
 28→
 29→  useEffect(() => {
 30→    document.title = t('appTitle');
 31→  }, [t]);
 32→
 33→  useEffect(() => {
 34→    if (tables.length === 0) {
 35→      setQueryResult(null);
 36→      setError(null);
 37→      setEditorQuery(undefined);
 38→    }
 39→  }, [tables]);
 40→
 41→  const handleAgentToggle = () => {
 42→    setAgentOpen((prev) => !prev);
 43→  };
 44→
 45→  const handleLoadSample = useCallback(async () => {
 46→    setError(null);
 47→    try {
 48→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 49→      if (!response.ok) throw new Error('Failed to load sample dataset');
 50→      await refreshTables();
 51→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 52→    } catch (e) {
 53→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 54→    }
 55→  }, [refreshTables]);
 56→
 57→  const handleFileUpload = useCallback(
 58→    async (files: File[]) => {
 59→      setError(null);
 60→      let lastName = '';
 61→      try {
 62→        for (const file of files) {
 63→          const formData = new FormData();
 64→          formData.append('file', file);
 65→          const response = await fetch('/api/upload', {
 66→            method: 'POST',
 67→            body: formData,
 68→          });
 69→          if (!response.ok) {
 70→            const errorData = await response.json();
 71→            throw new Error(errorData.detail || 'Failed to upload file');
 72→          }
 73→          const result = await response.json();
 74→          // Handle both single table and array of tables (Excel with multiple sheets)
 75→          if (Array.isArray(result)) {
 76→            lastName = result[result.length - 1]?.name || '';
 77→          } else {
 78→            lastName = result.name;
 79→          }
 80→        }
 81→        await refreshTables();
 82→        if (lastName) {
 83→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
 84→        }
 85→      } catch (e) {
 86→        setError(e instanceof Error ? e.message : 'Failed to upload file');
 87→      }
 88→    },
 89→    [refreshTables]
 90→  );
 91→
 92→  const handleQueryExecute = useCallback(
 93→    async (sql: string) => {
 94→      setError(null);
 95→      setQueryResult(null);
 96→      try {
 97→        const start = performance.now();
 98→        const response = await fetch('/api/query', {
 99→          method: 'POST',
100→          headers: { 'Content-Type': 'application/json' },
101→          body: JSON.stringify({ sql }),
102→        });
103→        const elapsed = performance.now() - start;
104→
105→        if (!response.ok) {
106→          const errorData = await response.json();
107→          throw new Error(errorData.detail || 'Query execution failed');
108→        }
109→
110→        const result = await response.json();
111→        setQueryResult({
112→          columns: result.columns,
113→          rows: result.rows,
114→          rowCount: result.rowCount,
115→          executionTimeMs: elapsed,
116→          resultType: result.resultType,
117→        });
118→        await refreshTables();
119→      } catch (e) {
120→        setError(e instanceof Error ? e.message : 'Query execution failed');
121→      }
122→    },
123→    [refreshTables]
124→  );
125→
126→  const handleTableClick = useCallback((tableName: string) => {
127→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
128→  }, []);
129→
130→  const handleTableDelete = useCallback(async (tableName: string) => {
131→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
132→    try {
133→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
134→        method: 'DELETE',
135→      });
136→      if (!response.ok) throw new Error('Failed to delete table');
137→      await refreshTables();
138→    } catch (e) {
139→      setError(e instanceof Error ? e.message : 'Failed to delete table');
140→    }
141→  }, [refreshTables, t]);
142→
143→  const handleDeleteAll = useCallback(async () => {
144→    if (tables.length === 0) return;
145→    if (!confirm(t('deleteAllTablesConfirm'))) return;
146→    try {
147→      for (const table of tables) {
148→        const response = await fetch(`/api/tables/${encodeURIComponent(table.name)}`, {
149→          method: 'DELETE',
150→        });
151→        if (!response.ok) throw new Error('Failed to delete table');
152→      }
153→      await refreshTables();
154→    } catch (e) {
155→      setError(e instanceof Error ? e.message : 'Failed to delete tables');
156→    }
157→  }, [tables, refreshTables, t]);
158→
159→  const appClass = [
160→    'app',
161→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
162→  ].filter(Boolean).join(' ');
163→
164→  const themeIcon = theme === 'dark' ? (
165→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
166→      <circle cx="12" cy="12" r="5" />
167→      <line x1="12" y1="1" x2="12" y2="3" />
168→      <line x1="12" y1="21" x2="12" y2="23" />
169→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
170→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
171→      <line x1="1" y1="12" x2="3" y2="12" />
172→      <line x1="21" y1="12" x2="23" y2="12" />
173→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
174→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
175→    </svg>
176→  ) : (
177→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
178→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
179→    </svg>
180→  );
181→
182→  return (
183→    <div className={appClass}>
184→      <div className="app__sidebar-wrapper">
185→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} onUpload={handleFileUpload} onDeleteAll={handleDeleteAll} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
186→      </div>
187→      {agentOpen ? (
188→        <div className="app__agent-wrapper">
189→          <div className="app__header">
190→            <h1 className="app__title">{t('appTitle')}</h1>
191→            <div className="app__header-actions">
192→              <button
193→                className="app__lang-toggle"
194→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
195→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
196→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
197→              >
198→                {language === 'en' ? 'EN' : '中'}
199→              </button>
200→              <button
201→                className="app__theme-toggle"
202→                onClick={toggleTheme}
203→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
204→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
205→              >
206→                {themeIcon}
207→              </button>
208→              <button
209→                className="app__agent-toggle app__agent-toggle--active"
210→                onClick={handleAgentToggle}
211→              >
212→                {t('editorMode')}
213→              </button>
214→            </div>
215→          </div>
216→          <AgentPanel
217→            langfuseStatus={langfuseStatus}
218→            tables={tables}
219→            onUpload={handleFileUpload}
220→            onLoadSample={handleLoadSample}
221→          />
222→        </div>
223→      ) : (
224→        <div className="app__editor-wrapper">
225→          <div className="app__header">
226→            <h1 className="app__title">{t('appTitle')}</h1>
227→            <div className="app__header-actions">
228→              <button
229→                className="app__lang-toggle"
230→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
231→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
232→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
233→              >
234→                {language === 'en' ? 'EN' : '中'}
235→              </button>
236→              <button
237→                className="app__theme-toggle"
238→                onClick={toggleTheme}
239→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
240→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
241→              >
242→                {themeIcon}
243→              </button>
244→              <button
245→                className="app__agent-toggle"
246→                onClick={handleAgentToggle}
247→              >
248→                {t('agentMode')}
249→              </button>
250→            </div>
251→          </div>
252→          <div className="app__mode-header">
253→            <span className="app__mode-title">{t('editorMode')}</span>
254→          </div>
255→          <main className="app__main">
256→            {tables.length === 0 ? (
257→              <div className="app__empty">
258→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
259→              </div>
260→            ) : (
261→              <>
262→                <QueryEditor
263→                  onExecute={handleQueryExecute}
264→                  initialQuery={editorQuery}
265→                />
266→                {error && (
267→                  <ErrorMessage message={error} onDismiss={() => setError(null)} />
268→                )}
269→                {queryResult?.resultType === 'markdown' ? (
270→                  <ResultMarkdown result={queryResult} />
271→                ) : (
272→                  <ResultsTable result={queryResult} />
273→                )}
274→              </>
275→            )}
276→          </main>
277→        </div>
278→      )}
279→    </div>
280→  );
281→}
282→
283→export default function App() {
284→  const [tables, setTables] = useState<TableInfo[]>([]);
285→  const [loading, setLoading] = useState(true);
286→  const [error, setError] = useState<string | null>(null);
287→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
288→
289→  const refreshTables = useCallback(async () => {
290→    try {
291→      const response = await fetch('/api/tables');
292→      if (!response.ok) throw new Error('Failed to fetch tables');
293→      const data = await response.json();
294→      setTables(data);
295→    } catch (e) {
296→      console.error('Failed to refresh tables:', e);
297→    }
298→  }, []);
299→
300→  useEffect(() => {
301→    (async () => {
302→      try {
303→        const response = await fetch('/api/health');
304→        if (!response.ok) throw new Error('Backend is not available');
305→        await refreshTables();
306→        try {
307→          const lfRes = await fetch('/api/langfuse/status');
308→          if (lfRes.ok) {
309→            setLangfuseStatus(await lfRes.json());
310→          }
311→        } catch {
312→          // Langfuse status fetch is non-critical
313→        }
314→      } catch (e) {
315→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
316→      } finally {
317→        setLoading(false);
318→      }
319→    })();
320→  }, [refreshTables]);
321→
322→  if (loading) {
323→    return <div className="app-loading">Connecting to backend...</div>;
324→  }
325→
326→  if (error) {
327→    return (
328→      <div className="app-error">Failed to connect: {error}</div>
329→    );
330→  }
331→
332→  return (
333→    <ConfigProvider>
334→      <LanguageProvider>
335→        <ThemeProvider>
336→          <AgentProvider refreshTables={refreshTables}>
337→            <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
338→          </AgentProvider>
339→        </ThemeProvider>
340→      </LanguageProvider>
341→    </ConfigProvider>
342→  );
343→}
