 1→export interface ColumnInfo {
 2→  name: string;
 3→  type: string;
 4→}
 5→
 6→export interface TableInfo {
 7→  name: string;
 8→  columns: ColumnInfo[];
 9→  rowCount: number;
10→}
11→
12→export interface QueryResult {
13→  columns: string[];
14→  rows: Record<string, unknown>[];
15→  rowCount: number;
16→  executionTimeMs: number;
17→  resultType: 'table' | 'markdown';
18→}
19→
20→export interface ToolCallResult {
21→  toolCallId: string;
22→  toolName?: string;
23→  sql: string;
24→  command?: string;
25→  toolInput?: Record<string, unknown>;
26→  columns: string[];
27→  rows: Record<string, unknown>[];
28→  rowCount: number;
29→  error?: string;
30→  output?: string;
31→  rawContent?: string;
32→}
33→
34→export interface ContentSegment {
35→  type: 'thinking' | 'tool' | 'answer';
36→  text?: string;
37→  toolResult?: ToolCallResult;
38→}
39→
40→export interface ChatMessage {
41→  id: string;
42→  role: 'user' | 'assistant';
43→  content: string;
